const scopes=[['Identity checked','Confirm the identity information submitted for the business.'],['Business checked','Review business registration or professional evidence.'],['Address checked','Confirm submitted operating-address evidence.'],['Portfolio checked','Review ownership or permission evidence for portfolio work.']];export default function TrustCenter(){return <main className="trust-page"><header className="portfolio-header"><a className="brand" href="/">WedConnect</a><span>Vendor trust center</span></header><section className="trust-hero"><p className="eyebrow">Verification</p><h1>Build trust with clear, qualified checks</h1><p>Submit only the minimum evidence required. Files remain private and every verifier view is recorded.</p></section><section className="trust-grid">{scopes.map(([name,text])=><article key={name}><div><span>Not started</span><h2>{name}</h2><p>{text}</p></div><button className="secondary" type="button">Start check</button></article>)}</section><aside className="badge-disclaimer"><strong>What a badge means</strong><p>Information submitted to WedConnect was checked for the displayed scope. It does not guarantee service quality, availability, safety or future conduct.</p></aside></main>}
